    const summaries = await sessionStore.listFor(session.userId, {
      limit: message.limit,
      before: message.before,
    });

    ws.send(JSON.stringify({type: 'session_list', sessions: summaries}));
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'failed to list conversations', {sessionId: session.sessionId, userId: session.userId, error: errorMessage});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

